package android.net;public final class Uri{private final String s;private Uri(String s){this.s=s;}public static Uri parse(String s){return new Uri(s);}public static Uri fromFile(java.io.File f){return new Uri(f.toURI().toString());}public String getScheme(){return java.net.URI.create(s).getScheme();}public String toString(){return s;}public int hashCode(){return s.hashCode();}public boolean equals(Object o){return o instanceof Uri&&s.equals(o.toString());}}
